def validate_order(payment_method: str, shipping_method: str, has_gift_wrap: bool, is_international: bool) -> dict:
    """Validate an order configuration and return a structured result.

    The function validates the combination of payment/shipping/options with real-world constraints.

    Normalization:
    - `payment_method` and `shipping_method` are normalized by `strip().lower()`.

    Accepted values:
    - payment_method: 'card', 'bank', 'cash'
    - shipping_method: 'standard', 'express', 'pickup'

    Type rules:
    - `has_gift_wrap` and `is_international` must be bool, otherwise TypeError.
    - Unknown payment/shipping values raise ValueError.

    Business constraints (all applicable errors should be reported):
    - International shipping cannot be 'pickup'.
    - 'cash' payment is domestic only.
    - Gift wrap is not available for 'pickup'.
    - Gift wrap is not available for international orders.
    - 'bank' payment is not allowed with 'express' shipping.
    - 'cash' payment is not allowed with 'express' shipping.

    Returns:
        A dict with keys:
        - is_valid: bool
        - errors: list[str] (error codes)
        - normalized: dict (normalized inputs)
    """
    if not isinstance(payment_method, str):
        raise TypeError("payment_method must be a str")
    if not isinstance(shipping_method, str):
        raise TypeError("shipping_method must be a str")
    if not isinstance(has_gift_wrap, bool):
        raise TypeError("has_gift_wrap must be a bool")
    if not isinstance(is_international, bool):
        raise TypeError("is_international must be a bool")

    pm = payment_method.strip().lower()
    sm = shipping_method.strip().lower()

    allowed_payments = {"card", "bank", "cash"}
    allowed_shipping = {"standard", "express", "pickup"}

    if pm not in allowed_payments:
        raise ValueError(f"Unknown payment_method: {payment_method}")
    if sm not in allowed_shipping:
        raise ValueError(f"Unknown shipping_method: {shipping_method}")

    errors: list[str] = []

    if is_international and sm == "pickup":
        errors.append("INTERNATIONAL_PICKUP_NOT_ALLOWED")

    if pm == "cash" and is_international:
        errors.append("CASH_DOMESTIC_ONLY")

    if sm == "pickup" and has_gift_wrap:
        errors.append("GIFT_WRAP_NOT_ALLOWED_FOR_PICKUP")

    if is_international and has_gift_wrap:
        errors.append("GIFT_WRAP_NOT_AVAILABLE_INTERNATIONAL")

    if pm == "bank" and sm == "express":
        errors.append("BANK_NOT_ALLOWED_FOR_EXPRESS")

    if pm == "cash" and sm == "express":
        errors.append("CASH_NOT_ALLOWED_FOR_EXPRESS")

    return {
        "is_valid": len(errors) == 0,
        "errors": errors,
        "normalized": {
            "payment_method": pm,
            "shipping_method": sm,
            "has_gift_wrap": has_gift_wrap,
            "is_international": is_international,
        },
    }

